/**
 * Session keys from the operator's own node, as Polkadot.js Apps gets them: the
 * node generates the keys in its keystore and signs their ownership proof, and the
 * operator's wallet registers them with `session.setKeys` over the public RPC.
 *
 * The node only serves these (unsafe) methods on its local interface, so the
 * caller reaches it on `ws://127.0.0.1` directly or through an SSH tunnel. Only
 * loopback URLs are accepted: keys generated by someone else's node are keys that
 * node's operator holds, and could double-sign (and get the validator slashed) with
 * them. Only `author_rotateKeysWithOwner` and `author_hasSessionKeys` are called:
 * never `author_insertKey`, which would send a seed.
 */
import { SubstrateClient } from '../../substrate/SubstrateClient';
import { substrateSs58ToAccountIdHex } from '../../../foundation/address';
import { isHexOfLength } from '../../../foundation/encoding/hex';
import type { SessionKeysWithProof } from './types/index';

const LOOPBACK_HOSTS = new Set(['localhost', '127.0.0.1', '[::1]']);

/** Whether `url` is a `ws://` or `wss://` URL on this machine (directly or tunnelled). */
export function isLoopbackNodeUrl(url: string): boolean {
    try {
        const { protocol, hostname, username, password } = new URL(url);
        return (
            (protocol === 'ws:' || protocol === 'wss:') &&
            LOOPBACK_HOSTS.has(hostname) &&
            !username &&
            !password
        );
    } catch {
        return false;
    }
}

/** A connection to the operator's node, checked to be on the expected chain. */
export class OperatorNode {
    private constructor(private readonly node: SubstrateClient) {}

    /**
     * Connects to `url` and checks the node's genesis is `genesisHash`: keys made
     * by a node of another chain would register but never author here.
     */
    static async connect(
        url: string,
        genesisHash: string,
        timeoutMs = 10_000
    ): Promise<OperatorNode> {
        if (!isLoopbackNodeUrl(url)) {
            throw new Error(
                'The node URL must be ws:// or wss:// on localhost (use an SSH tunnel)'
            );
        }
        if (!/^0x[0-9a-fA-F]{64}$/.test(genesisHash))
            throw new Error('genesisHash: not 32 bytes of 0x hex');
        const node = await SubstrateClient.connect(url, timeoutMs);
        try {
            const genesis = await node.request<string>('chain_getBlockHash', [0]);
            if (genesis.toLowerCase() !== genesisHash.toLowerCase()) {
                throw new Error(`operator node is on another chain (genesis ${genesis})`);
            }
        } catch (e) {
            node.destroy();
            throw e;
        }
        return new OperatorNode(node);
    }

    /**
     * New session keys in the node's keystore, with their signatures over `owner`
     * (the validator's stash). Fails when the node returns no proof: the runtime
     * refuses `setKeys` without one.
     */
    async rotateKeysWithOwner(owner: string): Promise<SessionKeysWithProof> {
        const ownerHex = substrateSs58ToAccountIdHex(owner);
        if (!ownerHex) throw new Error(`rotateKeysWithOwner.owner: not an SS58 account: ${owner}`);
        const result = await this.node.request<{ keys: string; proof?: string | null }>(
            'author_rotateKeysWithOwner',
            [ownerHex]
        );
        if (!isHexOfLength(result?.keys, 64))
            throw new Error('operator node returned no session keys');
        if (!result.proof || result.proof === '0x') {
            throw new Error('operator node returned no ownership proof; upgrade the node');
        }
        return { keys: result.keys, proof: result.proof };
    }

    /** Whether the node's keystore holds the private keys of `keys`. */
    async hasSessionKeys(keys: string): Promise<boolean> {
        if (!isHexOfLength(keys, 64))
            throw new Error('hasSessionKeys.keys: not 64 bytes of 0x hex');
        return (await this.node.request<unknown>('author_hasSessionKeys', [keys])) === true;
    }

    destroy(): void {
        this.node.destroy();
    }
}
